// Prepares the Cloudflare build (run by `npm run cf:dev` / `npm run cf:deploy`):
//  - worker/migrations.generated.js imports every server/db/migrations/*.sql, in order;
//  - dist/ is public/ plus a _headers file giving static files the same security headers as the API.
const fs = require('node:fs');
const path = require('node:path');

const root = path.join(__dirname, '..');
const migrationsDir = path.join(root, 'server', 'db', 'migrations');
const files = fs.readdirSync(migrationsDir).filter((f) => /^\d+_.*\.sql$/.test(f)).sort();
const lines = [
  '// Generated by scripts/build-worker.js from server/db/migrations. Do not edit.',
  ...files.map((f, i) => `import m${i} from '../server/db/migrations/${f}';`),
  '',
  'export const migrations = [',
  ...files.map((f, i) => `  { version: ${Number.parseInt(f, 10)}, sql: m${i} },`),
  '];',
  '',
];
fs.writeFileSync(path.join(root, 'worker', 'migrations.generated.js'), lines.join('\n'));

const dist = path.join(root, 'dist');
fs.rmSync(dist, { recursive: true, force: true });
fs.cpSync(path.join(root, 'public'), dist, { recursive: true });
const { SECURITY_HEADERS: headers } = require('../server/securityHeaders');
fs.writeFileSync(path.join(dist, '_headers'), `/*\n${Object.entries(headers).map(([k, v]) => `  ${k}: ${v}`).join('\n')}\n`);
console.log(`Worker build ready: ${files.length} migrations, dist/ from public/.`);
